        edges.append((2*col,2*col+1))
        if col+1<nc:
            edges.append((2*col,2*(col+1)))
            edges.append((2*col+1,2*(col+1)+1))
            if col%2==0:
                edges.append((2*col,2*(col+1)+1))
            else:
                edges.append((2*col+1,2*(col+1)))
    return edges

