    rng=np.random.default_rng(seed)
    single=('rx','ry','rz'); two=('rxx','ryy','rzz')
    edges=ladder_edges(n); tape=[]; pi=0
    for _ in range(layers):
      for q in range(n):
        axis=single[int(rng.integers(3))]; tape.append((axis,q,pi)); pi+=1
      e=list(edges); rng.shuffle(e); used=set()
      for a,b in e:
        if a in used or b in used: continue
        if rng.random()>p: continue
        axis=two[int(rng.integers(3))]; tape.append((axis,a,b,pi)); pi+=1; used.add(a); used.add(b)
